 let index=0,back=false;const flip=root.querySelector('#lx-demo-flip'),content=root.querySelector('#lx-demo-content');
 flip.onclick=()=>{if(back){index=(index+1)%words.length;back=false;}else back=true;const [uz,en,example]=words[index];content.innerHTML=back?`<span class="lx-card-label">Inglizcha javob</span><h2>${en}</h2><p>${example}</p>`:`<span class="lx-card-label">Inglizchasini eslaysizmi?</span><h2>${uz}</h2><p>Avval o‘zingiz eslab ko‘ring.</p>`;flip.innerHTML=back?'Keyingi so‘z <span>→</span>':'Javobni ochish <span>↻</span>';root.querySelector('#lx-demo-count').textContent=`0${index+1} / 03`;root.querySelector('#lx-demo-card').classList.toggle('lx-is-back',back);};
